     "title": "白宫将于周二会晤AI巨头 讨论前沿模型安全测试框架",
     "url": "http://finance.eastmoney.com/news/1354,202608043830161214.html",
     "time": "08-04 03:55",
     "ts": 1785786937,
     "summary": "美国白宫将于当地时间周二召集人工智能(AI)企业，就一项最新完成的框架展开讨论。该框架旨在评估行业内最先进AI模型的网络安全能力。 一位白宫官员表示，会议重点将围绕美国总统特朗普于今年6月下令制定的自愿性AI模型评估框架展开。 据消息人士透露，Anthropic预计将派代表参加会议，OpenAI和谷歌也预计将出席。白宫官员表示，政府目前正在与更广泛的行业合作伙伴展开合作，并计划与AI行业展开讨论。 此外，Meta公司发言人也证实，该公司已受邀于周二与白宫官员会面，讨论针对美国",
